import type { Meta, StoryObj } from '@storybook/preact-vite';
import {
  Skeleton,
  SkeletonProps,
  SkeletonRow,
  SkeletonRowProps,
} from './Skeleton';
import { expect } from 'storybook/test';

/**
 * Use Skeletons to display content placeholders while content is loading.
 */
const meta: Meta<SkeletonRowProps & SkeletonProps> = {
  title: 'Components/Skeleton',
  component: Skeleton,
  argTypes: {
    size: {
      type: 'string',
      options: ['xsmall', 'small', 'medium', 'large', 'xlarge'],
      control: {
        type: 'radio',
      },
      defaultValue: {
        summary: 'small',
      },
      description: 'Size of the skeleton',
    },
    variant: {
      type: 'string',
      options: ['row', 'heading', 'empty'],
      control: { type: 'radio' },
      defaultValue: {
        summary: 'row',
      },
      description: 'Variant of the skeleton',
    },
    fullWidth: {
      type: 'boolean',
      defaultValue: {
        summary: 'false',
      },
      description: 'Stretch the skeleton to full width',
    },
    lines: {
      type: 'number',
      defaultValue: {
        summary: '1',
      },
      description: 'No. of times to repeat the row',
    },
    multilineGap: {
      type: 'string',
      options: ['xsmall', 'small', 'medium', 'big', 'xbig'],
      control: { type: 'radio' },
      defaultValue: {
        summary: 'medium',
      },
      description: 'Vertical gap between multiline items',
    },
    rowGap: {
      type: 'string',
      options: ['xsmall', 'small', 'medium', 'big', 'xbig'],
      control: { type: 'radio' },
      defaultValue: {
        summary: 'medium',
      },
      description: 'Horizontal and vertical gap between SkeletonRows',
    },
  },
  decorators: [(Story) => <div style={{ width: '400px' }}>{Story()}</div>],
};

export default meta;

type Story = StoryObj<SkeletonRowProps & SkeletonProps>;

/**
 * Import the component to use in your components:
 *
 * ```ts
 * import { Skeleton, SkeletonRow } from '@adobe-commerce/elsie/components';
 * ```
 */

/**
 * Pass in an SVG element as a child to render a shimmering skeleton version of it.
 *
 * ```tsx
 * <Skeleton>
 *    <SkeletonRow>
 *     `<svg width="450" height="400">
 *        <rect x="43" y="304" rx="4" ry="4" width="271" height="9" />
 *        <rect x="44" y="323" rx="3" ry="3" width="119" height="6" />
 *        <rect x="42" y="77" rx="10" ry="10" width="388" height="217" />
 *     </svg>`
 *    </SkeletonRow>
 * </Skeleton>
 * ```
 */

export const SVG: Story = {
  args: {
    children: `<svg width="450" height="400">
        <rect x="43" y="304" rx="4" ry="4" width="271" height="9" />
        <rect x="44" y="323" rx="3" ry="3" width="119" height="6" />
        <rect x="42" y="77" rx="10" ry="10" width="388" height="217" />
      </svg>`,
  },
  render: (args) => {
    return (
      <Skeleton>
        <SkeletonRow>{args.children}</SkeletonRow>
      </Skeleton>
    );
  },
  play: async () => {
    const skeleton = document.querySelector('.dropin-skeleton') as HTMLElement;

    const skeletonRow = document.querySelector(
      '.dropin-skeleton-row',
    ) as HTMLElement;

    await expect(skeleton).toBeVisible();
    await expect(skeletonRow).toBeVisible();
  },
};

/**
 * Use a Row HTML element
 *
 * ```tsx
 * <Skeleton>
 *  <SkeletonRow variant="row" size="medium" />
 *  <SkeletonRow variant="row" size="medium" />
 *  <SkeletonRow variant="row" size="medium" />
 * </Skeleton>
 * ```
 */

export const Rows: Story = {
  args: {
    size: 'medium',
    variant: 'row',
    multilineGap: 'medium',
    rowGap: 'medium',
  },
  render: (args) => {
    return (
      <Skeleton rowGap={args.rowGap}>
        <SkeletonRow
          variant={args.variant}
          size={args.size}
          fullWidth={args.fullWidth}
          lines={args.lines}
          multilineGap={args.multilineGap}
        />
        <SkeletonRow
          variant={args.variant}
          size={args.size}
          fullWidth={args.fullWidth}
          lines={args.lines}
          multilineGap={args.multilineGap}
        />
        <SkeletonRow
          variant={args.variant}
          size={args.size}
          fullWidth={args.fullWidth}
          lines={args.lines}
          multilineGap={args.multilineGap}
        />
      </Skeleton>
    );
  },
};

