/**
 * HTML Example
 *
 * ```tsx
 * <Skeleton>
 *  <SkeletonRow variant="heading" size="medium" />
 *  <SkeletonRow variant="empty" size="medium" />
 *  <SkeletonRow size="medium" fullWidth={true} />
 *  <SkeletonRow size="medium" fullWidth={true} lines={3} />
 * </Skeleton>
 * ```
 */

export const HTMLExample: Story = {
  args: {
    size: 'medium',
    multilineGap: 'medium',
    rowGap: 'medium',
  },
  render: (args) => {
    return (
      <Skeleton rowGap={args.rowGap}>
        <SkeletonRow
          variant={'heading'}
          size={args.size}
          multilineGap={args.multilineGap}
        />
        <SkeletonRow
          variant={'empty'}
          size={args.size}
          multilineGap={args.multilineGap}
        />
        <SkeletonRow
          size={args.size}
          fullWidth={true}
          multilineGap={args.multilineGap}
        />
        <SkeletonRow
          size={args.size}
          fullWidth={true}
          lines={3}
          multilineGap={args.multilineGap}
        />
        <SkeletonRow size={args.size} multilineGap={args.multilineGap} />
        <SkeletonRow size={args.size} multilineGap={args.multilineGap} />
      </Skeleton>
    );
  },
};
